if の分岐から直接値を作る。この書き方を導入した Proposal は？

```swift
let score = 100
let message = if score == 100 {
    "Perfect!"
} else {
    "Try again"
}
```

`reserve` は `Stock` の外にある同期関数。在庫確認から減算まで、同じ actor 上の別タスクを割り込ませずに実行したい。`/* ? */` に入る修飾子と、その隔離の仕組みを導入した Proposal は？

```swift
actor Stock { var remaining = 1 }

func reserve(_ stock: /* ? */ Stock) -> Bool {
    guard stock.remaining > 0 else { return false }
    stock.remaining -= 1
    return true
}

func buy(_ stock: Stock) async {
    print(await reserve(stock))
}
```

`reserve` の本体は変更しない。Swift 6 言語モード、デフォルトの actor isolation は nonisolated とする。

`{ $0.name }` というクロージャーの代わりに、キーパスの式を map に直接渡せるようにした Proposal は？

```swift
struct User { let name: String }
let users = [User(name: "Mika"), User(name: "Ren")]

let names = users.map(\.name)
// ["Mika", "Ren"]
```

`any Sequence` として受け取った値を、下の `showCount(values)` のようにジェネリック関数へ直接渡せるようにした Proposal は？

```swift
func showCount<S: Sequence>(_ values: S) {
    print(values.reduce(0) { n, _ in n + 1 })
}

func show(_ values: any Sequence) {
    showCount(values)
}
```

`catch` の error をキャストせず `Result<T, E>` に格納でき、投げないクロージャーなら E が Never になる。この両方を可能にした Proposal は？

```swift
func capture<T, E: Error>(
    _ operation: () throws(E) -> T
) -> Result<T, E> {
    do { return .success(try operation()) }
    catch { return .failure(error) }
}

let result = capture { 42 }
// result の型は Result<Int, Never>
```

引数の `throws(E)` を単なる `throws` に変えると、同じ本体のままではコンパイルできない。

検索結果なしと通信失敗を区別したかったのに、missing と failed はどちらも `Int?` の nil になる。戻り値が既に Optional のとき、`try?` がもう一段 Optional を重ねない仕様に変えた Proposal は？

```swift
enum LookupError: Error { case offline }
func find(_ online: Bool) throws -> Int? {
    if !online { throw LookupError.offline }
    return nil
}

let missing = try? find(true)   // 成功したが結果なし
let failed = try? find(false)   // エラーが発生
```

この Dictionary の変換を、一度の呼び出しで書けるようにした Proposal は？

```swift
let scores = ["Swift": "100", "Mystery": "?"]
let numbers = scores.compactMapValues(Int.init)
// ["Swift": 100]
```

pair の2引数は同じ型 V が必要。それでも、表示が Image と Text に分かれる2回の badge 呼び出しを渡せる。分岐の結果を単一の具体型へ組み立てる変換を導入した Proposal は？

```swift
import SwiftUI
@ViewBuilder
func badge(_ ready: Bool) -> some View {
    if ready { Image(systemName: "checkmark") }
    else { Text("Waiting") }
}

func pair<V: View>(_ first: V, _ second: V) {}

pair(badge(true), badge(false))  // OK
// pair(Image(systemName: "checkmark"), Text("Waiting")) // NG
```

`Draft` は非 `Sendable` なクラス。新しく作った値を渡した後に使わないと解析し、この actor への引き渡しを許可した Proposal は？

```swift
final class Draft { var text = "" }
actor Inbox {
    var drafts: [Draft] = []
    func add(_ draft: Draft) { drafts.append(draft) }
}

@MainActor
func submit(to inbox: Inbox) async {
    let draft = Draft()
    draft.text = "Hello"
    await inbox.add(draft)
}
```

Swift 6 言語モード、デフォルトの actor isolation は nonisolated とする。

`Box<Int>` と `Box<Token>` はどちらも作れるが、duplicate に渡せるのは前者だけ。このように、非コピー可能な要素も受け入れつつ、要素次第でコンテナーをコピー可能にする拡張を導入した Proposal は？

```swift
struct Token: ~Copyable {}
struct Box<T: ~Copyable>: ~Copyable { var value: T }
extension Box: Copyable where T: Copyable {}

func duplicate<T>(_ value: T) -> (T, T) { (value, value) }

func demo() {
    let a = Box(value: 42)
    _ = duplicate(a)                 // OK
    let b = Box(value: Token())      // OK
    // _ = duplicate(b)              // コンパイルエラー
}
```
